export const sources={edital:"https://mid-rh.curitiba.pr.gov.br/Arquivo/Concurso/2026/Edital%20Normativo%20n%C2%B0%204-2026%20-%20LEGISLADOC%20-%20retifica%C3%A7%C3%A3o%204-2026%20Assinado.pdf",programa:"https://mid-rh.curitiba.pr.gov.br/Arquivo/Concurso/2026/Edital%20Normativo%20n%C2%B0%204-2026%20-%20LEGISLADOC%20-%20retifica%C3%A7%C3%A3o%204-2026%20Assinado.pdf#page=33",cronograma:"https://mid-rh.curitiba.pr.gov.br/Arquivo/Concurso/2026/Edital%20Normativo%20n%C2%B0%204-2026%20-%20LEGISLADOC%20-%20retifica%C3%A7%C3%A3o%204-2026%20Assinado.pdf#page=40",banca:'https://fafipa.selecao.net.br/concurso/4209-concurso-publico-do-municipio-de-curitiba-pr-medio',prefeitura:'https://concursos.curitiba.pr.gov.br/documento/00/0/2026/4/19/1/1',prova:'https://servicos.nc.ufpr.br/documentos/pmc20192/provas/501.pdf',gabarito:'https://servicos.nc.ufpr.br/documentos/pmc20192/provas/pmc2019_ed_6_2019_gabarito_definitivo.html',cf:'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm',lom:'https://legisladocexterno.curitiba.pr.gov.br/VisualizarHTML.aspx?id=335597',estatuto:'https://legisladocexterno.curitiba.pr.gov.br/VisualizarHTML.aspx?id=19296',organizacao:'https://legisladocexterno.curitiba.pr.gov.br/VisualizarHTML.aspx?id=360579',processo:'https://legisladocexterno.curitiba.pr.gov.br/VisualizarHTML.aspx?id=437437',licitacoes:'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm',improbidade:'https://www.planalto.gov.br/ccivil_03/leis/l8429.htm',lai:'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2011/lei/l12527.htm',lgpd:'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm',eca:'https://www.planalto.gov.br/ccivil_03/leis/l8069.htm',prioridade:'https://www.planalto.gov.br/ccivil_03/leis/l10048.htm',lindb:'https://www.planalto.gov.br/ccivil_03/decreto-lei/del4657.htm',usuario:'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13460.htm',arquivos:'https://www.planalto.gov.br/ccivil_03/leis/l8159.htm',manual:'https://www.gov.br/cidades/pt-br/midia/documentos/pdf/copy_of_manualderedacao.pdf',cert:'https://cartilha.cert.br/livro/',evg:'https://www.escolavirtual.gov.br/'};
export const subjects=[{id:'esp',name:'Conhecimentos Específicos',short:'Específicos',questions:20,points:50},{id:'por',name:'Língua Portuguesa',short:'Português',questions:5,points:12.5},{id:'log',name:'Raciocínio Lógico',short:'Raciocínio',questions:5,points:12.5},{id:'inf',name:'Noções de Informática',short:'Informática',questions:5,points:12.5},{id:'leg',name:'Legislação',short:'Legislação',questions:5,points:12.5}];
export type Lesson={id:string;subject:string;title:string;scope:string;body:string[];example:string;trap:string;recall:string;answer:string;source:string;minutes:number};
const L=(id:string,subject:string,title:string,scope:string,body:string[],example:string,trap:string,recall:string,answer:string,source=sources.programa):Lesson=>({id,subject,title,scope,body,example,trap,recall,answer,source,minutes:25});
export const lessons:Lesson[]=[
L('e01','esp','Princípios e organização da Administração','2.1.1',[
'Administrar é mobilizar pessoas e recursos para atingir objetivos. No setor público, esses objetivos devem atender ao interesse coletivo, com competência legal, controle e prestação de contas. A vontade pessoal do agente não substitui a autorização jurídica.',
'O art. 37 da Constituição explicita legalidade, impessoalidade, moralidade, publicidade e eficiência. Legalidade exige agir conforme o direito; impessoalidade afasta favorecimentos; moralidade exige atuação ética; publicidade permite controle; eficiência busca bons resultados com uso adequado dos recursos.',
'Administração direta reúne os órgãos das pessoas políticas. Na indireta existem entidades com personalidade própria, como autarquias. Desconcentração distribui atribuições entre órgãos da mesma pessoa; descentralização envolve outra pessoa. Órgão e entidade não são sinônimos.'
],'Uma secretaria que cria setores internos pratica desconcentração. A criação de uma autarquia envolve descentralização.','Publicidade não autoriza divulgar indiscriminadamente dados pessoais.','O que significa LIMPE?','Legalidade, impessoalidade, moralidade, publicidade e eficiência.',sources.cf),
L('e02','esp','Planejamento, organização, direção e controle','2.1.2–2.1.4',[
'Planejar significa definir resultados, prioridades, prazos e meios antes de agir. Organizar distribui recursos, responsabilidades e tarefas. Dirigir envolve comunicação, liderança e orientação. Controlar compara resultados com padrões e gera correções.',
'No ciclo PDCA, planeje uma melhoria, execute em escala adequada, verifique indicadores e aja sobre desvios. Indicador precisa de definição: tempo médio de atendimento, por exemplo, exige um marco de início e de fim, além de um período de medição.',
'Um processo transforma entradas em saídas por atividades relacionadas. Descreva quem recebe, quem analisa, quem decide e quem comunica. No ambiente de trabalho, ordene documentos, priorize prazos e mantenha padrões claros; uma mesa limpa sozinha não prova eficiência.'
],'Meta: reduzir erros de protocolo. Planejar: identificar causas. Organizar: atribuir conferência. Dirigir: orientar equipe. Controlar: comparar taxa de erros antes e depois.','Não confunda eficácia (atingir o objetivo) com eficiência (relação entre resultado e recursos).','Qual função compara o realizado com o planejado?','Controle.'),
L('e03','esp','Gestão de pessoas e relações de trabalho','2.1.5; 2.4.2',[
'Gestão de pessoas inclui distribuir responsabilidades, desenvolver competências, acompanhar desempenho e criar condições de colaboração. Competência combina conhecimento, habilidade e atitude: saber, saber fazer e agir de modo adequado.',
'Feedback útil descreve um comportamento observável, seu impacto e uma ação de melhoria. Evite rótulos sobre a personalidade. Um conflito pode revelar problemas de processo; escute as partes, examine fatos e busque uma solução compatível com as regras.',
'Liderança influencia a equipe; autoridade formal decorre do cargo. Delegação precisa de tarefa, limites, recursos e acompanhamento. Delegar não significa abandonar o controle, e nem toda competência pode ser delegada juridicamente.'
],'Em vez de “você é desorganizado”, diga: “três protocolos ficaram sem data; vamos usar uma lista de conferência na entrada”.','Grupo de pessoas não se torna equipe apenas por trabalhar na mesma sala.','Quais são os três componentes do CHA?','Conhecimentos, habilidades e atitudes.'),
L('e04','esp','Orçamento público: PPA, LDO e LOA','2.1.6',[
'O orçamento articula planejamento, autorização e controle. O PPA organiza diretrizes, objetivos e metas de médio prazo. A LDO orienta a elaboração do orçamento anual e estabelece prioridades. A LOA estima receitas e fixa despesas para o exercício.',
'Estudar orçamento exige distinguir autorização e execução: a existência de dotação não significa pagamento imediato. Na execução da despesa, empenho cria a obrigação de pagamento nas condições legais, liquidação verifica o direito do credor e pagamento quita a obrigação.',
'Princípios como unidade, universalidade e anualidade ajudam a interpretar questões. Orçamento não é apenas uma lista de compras: materializa escolhas públicas. Revise os arts. 165 a 169 como apoio ao tópico de orçamento, embora a faixa de artigos do bloco de Legislação seja distinta.'
],'Compra de material: reserva-se a dotação pelo empenho; comprova-se a entrega na liquidação; depois ocorre o pagamento.','Empenho, liquidação e pagamento são fases diferentes.','Qual instrumento estima receitas e fixa despesas anuais?','Lei Orçamentária Anual (LOA).',sources.cf),
L('e05','esp','Atos administrativos','2.2.1',[
'Ato administrativo é uma manifestação da Administração sob regime de direito público com efeitos jurídicos. Para estudá-lo, identifique competência, finalidade, forma, motivo e objeto. Competência é a atribuição legal; finalidade é o resultado público previsto; motivo reúne pressupostos de fato e de direito.',
'Motivo não é o mesmo que motivação: motivação é a exposição das razões. Mesmo em escolhas discricionárias, a Administração se submete à lei e aos limites de finalidade, razoabilidade e proporcionalidade.',
'Anulação corrige ilegalidade; revogação decorre de conveniência e oportunidade sobre ato válido, respeitados limites jurídicos. Nem todo ato possui todos os atributos: a imperatividade, por exemplo, não está presente em atos meramente enunciativos.'
],'Uma licença concedida por autoridade incompetente apresenta vício de competência. A mudança de preferência do gestor não transforma automaticamente um ato válido em ilegal.','Discricionariedade não é liberdade para agir arbitrariamente.','Qual a diferença central entre anular e revogar?','Anular: ilegalidade. Revogar: mérito administrativo de ato válido.'),
L('e06','esp','Bens e serviços públicos','2.2.2–2.2.3',[
'Bens públicos podem ser de uso comum do povo, de uso especial e dominicais. Uma praça é exemplo de uso comum; um prédio afetado a uma repartição, de uso especial. Dominicais integram o patrimônio público sem a mesma destinação pública específica.',
'Afetação é a destinação do bem a uma finalidade pública; desafetação retira essa destinação conforme o regime aplicável. Alienação de bem público depende de requisitos legais, e bens públicos não são adquiridos por usucapião.',
'Serviços públicos visam satisfazer necessidades coletivas. Continuidade, adequação, segurança e modicidade orientam a prestação. A execução pode ser direta ou delegada nos termos legais; a delegação não elimina o dever estatal de regulação e fiscalização.'
],'Compare uma rua, uma escola municipal em funcionamento e um terreno sem destinação: uso comum, uso especial e dominical.','Nem todo bem público está permanentemente fora de qualquer possibilidade de alienação.','Um edifício utilizado por uma secretaria é bem de qual espécie?','Bem de uso especial.'),
L('e07','esp','Licitações: mapa da Lei 14.133','2.2.4',[
'Licitar organiza a seleção de proposta vantajosa em condições isonômicas. Planejamento da contratação, transparência e julgamento objetivo são centrais. A proposta mais barata nem sempre representa o melhor resultado: considere o critério de julgamento permitido.',
'As modalidades são pregão, concorrência, concurso, leilão e diálogo competitivo. Não confunda modalidade com critério: menor preço e maior desconto são critérios. Pregão é utilizado para bens e serviços comuns conforme a lei.',
'A sequência ordinária compreende fase preparatória, divulgação do edital, propostas e lances quando cabíveis, julgamento, habilitação, recursos e homologação. A inversão da habilitação exige condições legais. Leia os arts. 5, 17, 28 e 33 na fonte.'
],'Comprar papel padronizado e selecionar um trabalho artístico não são situações idênticas; identifique a natureza do objeto antes da modalidade.','Convite e tomada de preços não integram as modalidades da Lei 14.133.','Cite as cinco modalidades da Lei 14.133.','Pregão, concorrência, concurso, leilão e diálogo competitivo.',sources.licitacoes),
L('e08','esp','Contratação direta e execução de contratos','2.2.4',[
'Contratação direta inclui dispensa e inexigibilidade. Na inexigibilidade há inviabilidade de competição; a dispensa depende de hipótese legal mesmo quando a competição seria possível. Contratação direta também exige processo e justificativas.',
'O contrato deve ser acompanhado por representantes designados. O fiscal registra ocorrências, verifica a execução e encaminha problemas que ultrapassem sua competência. Medição, recebimento e pagamento precisam de evidências, não apenas de confiança no fornecedor.',
'Estude sanções, alterações, garantias e extinção contratual na lei. Valores de dispensa podem ser atualizados: evite memorizar valores antigos encontrados em provas ou apostilas. Foque primeiro em conceitos e consulte os limites vigentes aplicáveis ao edital.'
],'Fornecedor exclusivo pode levar à inexigibilidade, desde que a exclusividade e os demais requisitos sejam comprovados no processo.','Contratação direta não significa contratação sem formalização ou controle.','O que caracteriza a inexigibilidade?','Inviabilidade de competição.',sources.licitacoes),
L('e09','esp','Processo administrativo em Curitiba','2.1.3; 2.2.5',[
'A Lei Municipal 16.466/2024 disciplina o processo administrativo local. Não transfira automaticamente prazos e regras da Lei Federal 9.784 para Curitiba. Leia a norma municipal identificando interessados, competência, impedimento, comunicação e decisão.',
'Um roteiro de estudo é: início do processo, instrução, manifestação do interessado, decisão motivada e eventual recurso. Instrução reúne elementos necessários para decidir; a decisão deve demonstrar sua relação com fatos e fundamentos.',
'Contraditório oferece a oportunidade de conhecer e contestar elementos; ampla defesa permite usar meios admitidos para defender interesses. Organize uma tabela própria de prazos a partir da redação vigente, registrando artigo, início da contagem e possibilidade de prorrogação.'
],'Se um documento essencial estiver ausente, identifique a providência prevista na lei e a forma de comunicar o interessado, em vez de indeferir por hábito.','O anexo do edital apresenta datas divergentes para algumas leis municipais. Use o número da lei e confira seu texto oficial e eventuais retificações.','Qual lei local você deve abrir para estudar processo administrativo?','Lei Municipal 16.466/2024.',sources.processo),
L('e10','esp','Responsabilidade e processo disciplinar','2.2.6–2.2.7',[
'O servidor pode responder nas esferas administrativa, civil e penal, segundo pressupostos próprios. Processo disciplinar apura infrações funcionais e deve respeitar garantias; não equivale automaticamente a processo criminal.',
'No Estatuto municipal, localize deveres, proibições, responsabilidades, penalidades e regras de apuração. Leia hipóteses, autoridades competentes e prazos com o texto aberto. Uma acusação isolada não autoriza antecipar a sanção.',
'Improbidade possui disciplina específica na Lei 8.429, alterada pela Lei 14.230. A lei exige conduta dolosa tipificada; ilegalidade por si só não é sinônimo de improbidade. Compare enriquecimento ilícito, dano ao erário e atos contra princípios, sem usar versões antigas da lei.'
],'Um erro material corrigível no cadastro e um desvio intencional de recursos exigem análise de fatos e enquadramentos diferentes.','Não conclua que qualquer falha ou ineficiência constitui improbidade.','Quais três esferas de responsabilidade costumam ser estudadas?','Administrativa, civil e penal.',sources.improbidade),
L('e11','esp','Constituição: poder constituinte e interpretação','2.3.1–2.3.6',[
'A Constituição ocupa posição superior no ordenamento. Poder constituinte originário cria uma nova ordem; o derivado reformador altera a Constituição segundo limites e procedimentos nela previstos. Emenda constitucional não pode ignorar esses limites.',
'Normas de eficácia plena produzem seus efeitos essenciais desde a entrada em vigor; normas de eficácia contida admitem restrições legais; normas de eficácia limitada dependem de integração para a plenitude de seus efeitos. Todas possuem relevância jurídica.',
'Interpretação constitucional deve considerar a unidade do texto e a harmonização entre disposições. A União não é superior aos estados ou municípios em toda matéria: há repartição de competências. Estude também o art. 37 sobre concurso, cargos e acumulação.'
],'Uma emenda é manifestação do poder constituinte derivado; uma lei ordinária não pode afastar a Constituição.','Lei federal não prevalece automaticamente sobre toda lei municipal: verifique a competência.','Qual poder cria uma nova ordem constitucional?','Poder constituinte originário.',sources.cf),
L('e12','esp','Ética, integridade e atendimento ao cidadão','2.4.1–2.4.4',[
'Ética no serviço público envolve finalidade pública, respeito, honestidade e decisões justificáveis. Um conflito de interesses surge quando interesses privados podem comprometer a atuação funcional. Reconhecer e encaminhar o conflito é melhor do que tratá-lo como algo irrelevante.',
'Atendimento adequado combina escuta, linguagem compreensível, informação correta e encaminhamento. A Lei 13.460 organiza direitos do usuário, manifestações e avaliação de serviços. A Carta de Serviços informa serviços, formas de acesso e compromissos de atendimento.',
'Comunicação tem emissor, receptor, mensagem, canal, código, contexto e possíveis ruídos. Confirme a compreensão com uma pergunta objetiva. Em reclamações, registre fatos e protocolo; evite prometer decisões de terceiros ou prazos sem fundamento.'
],'Diante de um cidadão irritado: escute, resuma o pedido, informe a etapa e explique o próximo passo em linguagem simples.','Tratar com respeito não significa favorecer conhecidos ou ignorar prioridades legais.','Para que serve a Carta de Serviços?','Informar serviços, requisitos, formas de acesso e padrões de atendimento.',sources.usuario),
L('e13','esp','Gestão da informação e arquivologia','2.5.1–2.5.2',[
'Dados são registros; informação resulta de organização e contexto. Um sistema de informação articula pessoas, processos e tecnologia. Qualidade da informação inclui precisão, relevância, completude, acessibilidade adequada e atualização.',
'Arquivos são conjuntos de documentos produzidos e recebidos no exercício de atividades. O princípio da proveniência preserva a origem dos documentos. Gestão documental acompanha produção, tramitação, uso, avaliação e destinação.',
'Documentos correntes têm uso frequente; intermediários aguardam destinação com uso menos frequente; permanentes possuem valor que justifica guarda definitiva. Tabela de temporalidade orienta prazos e destinação. A eliminação de documentos públicos depende de procedimentos e autorização competentes.'
],'Um processo em andamento tende a ser corrente; encerrado e ainda sujeito a prazo de guarda pode ser intermediário.','Documento antigo não é automaticamente permanente, e digitalização não autoriza descarte automático.','O que a tabela de temporalidade orienta?','Prazos de guarda e destinação dos documentos.',sources.arquivos),
L('e14','esp','Redação oficial e correspondência','2.5.3–2.5.4',[
'Redação oficial busca clareza, precisão, objetividade, concisão, coesão, impessoalidade e uso da norma-padrão. Impessoalidade se refere ao caráter institucional da mensagem; não exige escrever de modo rebuscado ou eliminar todo sujeito.',
'Antes de redigir, identifique destinatário, finalidade, informação principal e ação esperada. Organize contexto essencial, pedido ou resposta, fundamento quando necessário e encaminhamento. Revise referências, datas, nomes e anexos.',
'Correspondência comercial também exige adequação ao destinatário e ao objetivo, mas não se confunde com comunicação oficial. Use o Manual de Redação como referência de estudo e observe normas locais quando aplicáveis ao órgão.'
],'“Solicito o envio do relatório até 20 de outubro para concluir a análise” é mais claro que uma frase longa com fórmulas vagas.','Concisão elimina excessos, não informações indispensáveis.','Quais duas perguntas orientam a redação de um pedido?','O que deve ser feito e para qual finalidade?',sources.manual),
L('e15','esp','Métodos e técnicas de pesquisa','2.6',[
'Uma pesquisa começa por problema delimitado e objetivo claro. Defina o que quer descobrir, com quem ou sobre quais documentos e em qual período. Hipótese é uma resposta provisória a ser examinada, não uma conclusão antecipada.',
'Pesquisa quantitativa trabalha com medidas e análises numéricas; qualitativa explora significados, experiências e contextos. Podem ser combinadas. Pesquisa bibliográfica usa trabalhos publicados; documental analisa documentos como registros administrativos.',
'População é o conjunto de interesse; amostra é a parcela observada. Questionário, entrevista e observação são técnicas de coleta. Perguntas tendenciosas e amostras de conveniência podem distorcer resultados; correlação não basta para demonstrar causalidade.'
],'Para estudar satisfação, entrevistar apenas quem elogiou o serviço tende a produzir viés de seleção.','Uma amostra maior não corrige necessariamente uma seleção enviesada.','Qual a diferença entre população e amostra?','População é o conjunto de interesse; amostra é uma parte dele.'),
L('p01','por','Interpretação, inferência e ponto de vista','1.1.1; 1.1.7',[
'Primeiro leia o comando: ele pede informação explícita, inferência ou opinião do autor? Depois identifique assunto, tese e argumentos. Assunto é o tema geral; tese é a posição defendida. Uma frase verdadeira no mundo pode não ser sustentada pelo texto.',
'Inferir é concluir a partir de pistas textuais, sem acrescentar premissas sem apoio. Observe marcadores como “alguns”, “sempre”, “pode” e “necessariamente”: trocar um deles muda a força da afirmação.',
'Para resolver, localize o trecho de apoio e compare alternativa por alternativa. Elimine extrapolação, contradição, redução indevida e inversão de causa e consequência. Em semântica, o contexto determina o sentido da palavra, não apenas o dicionário.'
],'Texto autoral: “O canal digital ampliou o acesso, mas parte da população ainda depende do atendimento presencial.” Conclusão sustentada: os canais coexistem; não se pode inferir que o presencial seja dispensável.','Opinião do narrador ou personagem não é automaticamente a opinião do autor.','O que diferencia inferência de extrapolação?','Inferência tem apoio no texto; extrapolação acrescenta algo não sustentado.'),
L('p02','por','Gêneros, linguagem, coesão e coerência','1.1.2–1.1.4',[
'Gênero é uma forma social de comunicação, como notícia, requerimento ou receita. Tipologia é a organização linguística predominante: narração, descrição, exposição, argumentação ou injunção. Um gênero pode combinar tipologias.',
'Coesão conecta partes do texto por pronomes, repetição controlada, elipses e conectivos. Coerência é a articulação de sentidos. “Mas” costuma introduzir oposição; “portanto”, conclusão; “porque”, explicação ou causa conforme o contexto.',
'Variação linguística envolve região, grupo, época e situação. Adequação ao contexto não se confunde com inferioridade de uma variedade. Em comunicação oficial e questões de norma-padrão, use o registro solicitado.'
],'“O documento chegou. Ele será analisado.” O pronome “ele” retoma “documento”. Se houver dois antecedentes possíveis, a referência pode ficar ambígua.','Trocar conectivos apenas porque as frases continuam gramaticais pode alterar o sentido.','Notícia é gênero ou tipologia?','É gênero textual; pode conter diferentes tipologias.'),
L('p03','por','Ortografia, sons e acentuação','1.1.5; 1.1.11',[
'Letra representa a escrita; fonema corresponde a uma unidade sonora distintiva. Dígrafo é a representação de um fonema por duas letras, como “ch” em “chave”. Encontro consonantal reúne consoantes com sons distintos, como “pr” em “prato”.',
'Identifique a sílaba tônica antes de aplicar a regra: oxítona, paroxítona ou proparoxítona. Todas as proparoxítonas são acentuadas. Revise ditongos, hiatos e as alterações do acordo ortográfico com exemplos, evitando decorar listas sem regra.',
'Por que aparece em perguntas e equivale a “por qual razão” em diversos contextos; porque introduz explicação; por quê ocorre antes de pausa final; porquê é substantivo e admite determinante. Teste a função, não só a posição na frase.'
],'“Por que o pedido voltou? Voltou porque faltou assinatura. Você sabe por quê? Esse é o porquê da devolução.”','Nem toda sequência de duas vogais forma ditongo: em “saída” há hiato.','Qual forma pode ser precedida de “o” com sentido de motivo?','Porquê.'),
L('p04','por','Classes de palavras, sintaxe e concordância','1.1.6; 1.1.8–1.1.9',[
'A classe de uma palavra depende de seu uso. Substantivo nomeia; adjetivo caracteriza; verbo expressa processo; advérbio modifica verbo, adjetivo ou outro advérbio; pronome substitui ou acompanha nome. Uma mesma palavra pode exercer funções diferentes.',
'Encontre o verbo e pergunte qual é seu sujeito. Identifique núcleo do sujeito e complementos antes de julgar concordância. O verbo normalmente concorda com o núcleo do sujeito, não com o termo mais próximo.',
'Haver com sentido de existir é impessoal e permanece no singular. Existir possui sujeito e concorda com ele. Na concordância nominal, observe a palavra a que o adjetivo se refere. Regência ajuda a identificar complementos e a ocorrência de crase.'
],'“Havia documentos pendentes” e “Existiam documentos pendentes” estão corretas. “A lista de documentos chegou” concorda com “lista”.','Não separe sujeito de verbo com vírgula apenas porque o sujeito é longo.','Como fica “haver” no sentido de existir?','No singular: havia, houve, haverá documentos.'),
L('p05','por','Pontuação e construção de sentido','1.1.10; apoio à sintaxe',[
'Pontuação organiza relações sintáticas e sentidos. A vírgula separa elementos de enumeração, isola vocativo e pode marcar termos deslocados. Não se usa vírgula para separar diretamente sujeito de predicado ou verbo de seu complemento sem elemento intercalado.',
'Orações adjetivas restritivas delimitam o grupo; explicativas acrescentam informação sobre o referente e são isoladas por vírgulas. Ao retirar ou inserir vírgulas, examine a mudança de sentido, não apenas uma regra memorizada.',
'Dois-pontos podem introduzir esclarecimento ou enumeração. Aspas podem indicar citação, ironia ou uso especial. Ponto e vírgula organiza unidades relacionadas, especialmente quando já possuem vírgulas internas.'
],'“Os servidores que concluíram o curso receberam certificado” restringe o grupo. “Os servidores, que concluíram o curso, receberam certificado” apresenta a conclusão como informação sobre o grupo referido.','Vírgula não é simplesmente uma marca de respirar.','Qual termo de chamamento é isolado por vírgula?','O vocativo: “Senhora, aguarde um instante”.'),
L('p06','por','Literatura brasileira e figuras de linguagem','1.1.12',[
'Prosa se organiza usualmente em parágrafos; poesia explora ritmo, imagens e organização expressiva, sem se limitar à rima. Diferencie autor, narrador e eu lírico. Um narrador pode ser personagem, observador ou onisciente.',
'Para um mapa inicial: Romantismo — José de Alencar e Gonçalves Dias; Realismo — Machado de Assis; Naturalismo — Aluísio Azevedo; Parnasianismo — Olavo Bilac; Simbolismo — Cruz e Sousa; Modernismo — Mário de Andrade, Oswald de Andrade e Manuel Bandeira. Esse mapa não esgota autores e obras.',
'Metáfora aproxima sentidos sem conectivo comparativo explícito; comparação usa expressão comparativa; metonímia trabalha associação; hipérbole exagera; personificação atribui traços humanos; antítese opõe ideias. Identifique o efeito no texto.'
],'“A fila era um rio” é metáfora. “Esperei uma eternidade” é hipérbole. “O relógio reclamava” é personificação.','Nem toda poesia tem rima e nem todo narrador representa o pensamento do autor.','Qual figura atribui características humanas a algo não humano?','Personificação ou prosopopeia.'),
L('m01','log','Operações, frações e estimativas','1.2.1–1.2.2; 1.2.19',[
'Resolva primeiro parênteses; depois potências quando houver; em seguida multiplicações e divisões, da esquerda para a direita; finalmente adições e subtrações. Multiplicar números negativos segue a regra de sinais, diferente da soma.',
'Para somar frações, use denominador comum. Para multiplicar, multiplique numeradores e denominadores. Para dividir por uma fração não nula, multiplique pelo inverso. Transforme unidades antes de combinar valores.',
'Estimativa verifica se a resposta faz sentido. Arredondar é substituir por valor próximo com a precisão desejada; não arredonde etapas intermediárias sem necessidade. Em problemas, registre dados, incógnita, operação e unidade final.'
],'3 + 2 × 5 = 13, não 25. Já (3 + 2) × 5 = 25. E 1/2 + 1/3 = 3/6 + 2/6 = 5/6.','Somar denominadores ao somar frações é um erro comum.','Quanto é 3/4 dividido por 1/2?','3/4 × 2 = 3/2 = 1,5.'),
L('m02','log','Razão, proporção e regra de três','1.2.15–1.2.17',[
'Razão compara duas grandezas por divisão; proporção é uma igualdade de razões. Se a/b = c/d, com denominadores não nulos, então ad = bc. Antes de montar contas, verifique se as unidades são compatíveis.',
'Grandezas diretamente proporcionais crescem ou diminuem juntas na mesma razão. Nas inversamente proporcionais, aumentar uma reduz a outra na razão inversa, mantidas as condições do problema.',
'Em regra de três composta, analise cada grandeza em relação à incógnita. Mais trabalhadores reduzem o tempo apenas se a produtividade e a quantidade de trabalho forem mantidas e se o trabalho puder ser dividido como suposto.'
],'3 atendentes fazem um lote em 8 horas. Com mesma produtividade, 6 atendentes fazem em 4 horas: 3 × 8 = 6 × t.','Nem toda relação entre duas grandezas é proporcional.','Dobrar trabalhadores reduz tempo em que situação ideal?','Quando o trabalho é fixo, divisível e a produtividade individual é mantida.'),
L('m03','log','Porcentagem e juros simples','1.2.18',[
'Porcentagem é uma razão por cem. Para calcular 15% de 200, faça 0,15 × 200. Aumento de p% multiplica por 1 + p/100; desconto multiplica por 1 − p/100.',
'Variações sucessivas são multiplicadas, não simplesmente somadas. Um aumento de 20% seguido de desconto de 20% produz fator 1,2 × 0,8 = 0,96: queda final de 4% em relação ao valor inicial.',
'Nos juros simples, J = C × i × t e M = C + J. Use taxa na forma decimal e faça taxa e tempo terem a mesma unidade. Se a taxa é mensal, converta o prazo para meses. Sistema monetário exige atenção a centavos e arredondamento.'
],'R$ 1.000 a 2% ao mês por 3 meses: J = 1000 × 0,02 × 3 = R$ 60; montante R$ 1.060.','20% de 100 não é igual a 20% de 120. A base importa.','Qual a fórmula dos juros simples?','J = capital × taxa × tempo.'),
L('m04','log','Geometria, áreas e Teorema de Tales','1.2.3–1.2.7',[
'Perímetro mede contorno; área mede superfície. Retângulo: A = base × altura. Triângulo: A = base × altura / 2. Círculo: A = πr². Comprimento da circunferência: C = 2πr. Raio é metade do diâmetro.',
'No Teorema de Tales, retas paralelas cortadas por transversais determinam segmentos proporcionais. Monte razões na mesma ordem e confirme quais segmentos correspondem. Não some segmentos sem observar a figura.',
'Para áreas, a conversão de unidade muda ao quadrado: 1 m² = 10.000 cm². Em orientação, marque uma direção inicial; virar à direita a partir do norte leva ao leste. Girar o desenho mentalmente sem referência aumenta erros.'
],'Um retângulo de 6 m por 4 m tem área 24 m² e perímetro 20 m. Um círculo de raio 3 tem área 9π e comprimento 6π.','Não use diâmetro no lugar de raio na fórmula da área.','Quanto é 1 m² em cm²?','10.000 cm².'),
L('m05','log','Estatística e leitura de gráficos','1.2.8–1.2.9',[
'Média aritmética é soma dos valores dividida pela quantidade. Mediana é o valor central depois de ordenar os dados; se a quantidade é par, tire a média dos dois centrais. Moda é o valor de maior frequência, podendo não existir ou haver mais de uma.',
'Em gráficos, leia título, eixos, escala, unidade, legenda e período. Barras com eixo truncado podem exagerar diferenças visuais. Frequência absoluta é contagem; relativa é proporção do total.',
'Média ponderada usa pesos: multiplique cada valor pelo peso, some e divida pela soma dos pesos. Um valor extremo pode deslocar muito a média, mas nem sempre a mediana.'
],'Para 2, 2, 5, 7, 9: média = 25/5 = 5; mediana = 5; moda = 2.','A mediana exige ordenar os valores antes de escolher o centro.','Como se calcula média ponderada?','Soma dos produtos valor × peso, dividida pela soma dos pesos.'),
L('m06','log','Sequências e probabilidade','1.2.10–1.2.14',[
'Em sequências, teste diferenças, razões, alternância e padrões por posição. Uma lista finita pode aceitar vários padrões; escolha o que atende ao comando e às alternativas sem inventar regras arbitrárias.',
'Em resultados equiprováveis, P(A) = casos favoráveis / casos possíveis. A probabilidade de evento impossível é 0 e de evento certo é 1. A complementar vale P(não A) = 1 − P(A).',
'Na união, P(A ou B) = P(A) + P(B) − P(A e B). Na interseção de eventos independentes, multiplique probabilidades. Sem independência, use a probabilidade condicional: retirar objetos sem reposição altera o espaço da segunda retirada.'
],'Em um dado justo, P(par) = 3/6 = 1/2. Em duas moedas justas independentes, P(duas caras) = 1/2 × 1/2 = 1/4.','Eventos independentes não são o mesmo que eventos mutuamente exclusivos.','Por que retirar sem reposição pode gerar dependência?','Porque a primeira retirada altera as possibilidades da segunda.'),
L('i01','inf','Hardware, software e arquivos','1.3.1–1.3.5',[
'Hardware é a parte física; software é o conjunto de instruções. CPU executa instruções; RAM guarda dados de trabalho de modo volátil; SSD e HD armazenam dados de modo persistente. Capacidade de armazenamento não é medida de velocidade do processador.',
'Teclado e scanner são exemplos de entrada; monitor e impressora, de saída; dispositivos podem combinar funções. Sistema operacional gerencia recursos e serve de base para aplicativos.',
'Arquivos têm nome, extensão, local e metadados. Copiar cria outra instância; mover muda a localização. Extensão não garante segurança. Atalhos dependem de aplicativo, idioma e ambiente; Ctrl+C e Ctrl+V são amplamente usados para copiar e colar.'
],'Renomear “relatorio.exe” para “relatorio.pdf” não transforma um programa em documento PDF.','Sincronizar um arquivo não equivale, por si só, a ter uma cópia de segurança independente.' , 'Qual memória costuma perder dados quando o equipamento é desligado?','RAM.'),
L('i02','inf','Windows 10/11 e Linux Ubuntu','1.3.7; 1.3.4–1.3.5',[
'No Windows, o Explorador organiza arquivos e pastas; a barra de tarefas alterna aplicativos. No Ubuntu, o gerenciador de arquivos e o ambiente gráfico exercem funções semelhantes, embora caminhos, permissões e comandos sejam diferentes.',
'No Windows, Win+E abre o Explorador e Alt+Tab alterna janelas. No Linux, caminhos partem da raiz /; nomes de arquivos normalmente diferenciam maiúsculas de minúsculas. Diretório pessoal e raiz do sistema não são a mesma coisa.',
'Permissões controlam leitura, escrita e execução. Pratique localizar um arquivo, criar pasta, copiar, renomear e identificar propriedades. Diferencie excluir para lixeira e exclusão que a ignora. Faça exercícios com arquivos de teste, nunca com documentos essenciais.'
],'“Documento.txt” e “documento.txt” podem ser arquivos distintos em um sistema Linux comum.','Não generalize um atalho de um editor para todos os programas.' , 'Qual atalho abre o Explorador de Arquivos no Windows?','Win+E.'),
L('i03','inf','Word 2016 e redação de documentos','1.3.8',[
'No Word, distinga caractere, parágrafo, seção e documento. Negrito afeta caracteres; alinhamento e espaçamento afetam parágrafos; margens e orientação relacionam-se à configuração de página e seção.',
'Estilos aplicam formatação consistente e permitem estruturar títulos e sumário. Quebra de página inicia outra página; não substitua esse recurso por dezenas de Enter. Cabeçalho e rodapé organizam elementos recorrentes.',
'Salvar preserva alterações; Salvar como permite escolher novo nome, local ou formato. Exportar PDF ajuda a manter apresentação, mas não transforma o conteúdo em verdade ou garante confidencialidade. Revise ortografia, margens e visualização de impressão.'
],'Para numerar capítulos e criar sumário consistente, aplique estilos de título aos parágrafos, em vez de apenas aumentar a fonte.','Alinhar ao centro não é o mesmo que usar tabulação ou inserir espaços.' , 'Por que usar estilos de título?','Para manter estrutura e formatação consistentes e apoiar sumário automático.'),
L('i04','inf','Excel 2016: fórmulas e referências','1.3.9',[
'Uma célula é identificada por coluna e linha, como B3. Fórmulas começam com =. Em Excel em português, SOMA adiciona valores e MÉDIA calcula a média. O separador de argumentos depende da configuração regional; nos exemplos use ponto e vírgula.',
'Referência relativa muda ao copiar: A1. Absoluta fixa coluna e linha: $A$1. Mista fixa só uma dimensão: $A1 ou A$1. Identifique de onde a fórmula sai e para onde vai antes de deslocar referências.',
'A função SE avalia condição e retorna um resultado para verdadeiro e outro para falso. Classificar muda a ordem; filtrar exibe um subconjunto. Confira se uma operação abrange toda a tabela para não separar nomes dos respectivos valores.'
],'=SE(B2>=60;"Atingiu";"Revisar") testa a nota. Ao copiar =A1+$B$1 uma linha abaixo, obtém-se =A2+$B$1.','Mostrar uma célula como porcentagem altera apresentação; confira o valor armazenado.' , 'O que fica fixo em $A$1?','A coluna A e a linha 1.'),
L('i05','inf','Internet, e-mail, nuvem e segurança','1.3.6; 1.3.10–1.3.13',[
'Navegador acessa recursos da Web; buscador localiza páginas. URL identifica um recurso. HTTPS protege o transporte, mas não prova que o conteúdo ou vendedor é confiável. Examine domínio, contexto e origem das mensagens.',
'Em e-mail, Para indica destinatários principais; Cc envia cópia visível; Cco oculta os destinatários desse campo dos demais. Desconfie de anexos, urgência artificial e pedidos de senha. Phishing tenta induzir a pessoa a revelar dados ou executar ações.',
'No Google Drive, leitor, comentador e editor têm permissões diferentes. Restrinja compartilhamento ao necessário. Use senhas únicas, autenticação multifator, atualizações e backups testados; sincronização pode replicar exclusões e arquivos corrompidos.'
],'Uma mensagem com logotipo oficial e pedido urgente de senha ainda pode ser fraude. Acesse o serviço pelo endereço conhecido para conferir.','HTTPS e logotipo não bastam para legitimar uma página.' , 'Qual campo oculta destinatários de cópia?','Cco (cópia oculta).',sources.cert),
L('i06','inf','IA e ferramentas generativas: uso crítico','1.3.14',[
'Ferramentas como ChatGPT, Copilot e Gemini podem gerar texto a partir de instruções. Uma resposta fluente não é prova de precisão: o resultado pode conter erros, referências inexistentes ou informações desatualizadas.',
'Uma instrução útil informa tarefa, contexto, público, formato e critérios. Para estudar, peça exemplos, compare com a fonte e resolva novamente sem ajuda. Para textos normativos, confira o documento oficial e sua versão antes de aceitar uma explicação.',
'Evite inserir dados pessoais ou documentos sigilosos sem autorização e fundamento. A responsabilidade por verificar e usar o resultado permanece com a pessoa e a instituição. Interfaces e funcionalidades mudam; o conteúdo desta aula trata dos conceitos gerais, não de um catálogo de recursos.'
],'Pedido útil: “Explique a diferença entre média e mediana, dê um exemplo com cinco valores e confira as contas”. Depois refaça o cálculo.','Conteúdo gerado não substitui fonte primária, revisão humana ou julgamento crítico.' , 'Uma resposta convincente de IA garante exatidão?','Não. É preciso verificar fatos, cálculos e referências.'),
L('l01','leg','Constituição: roteiro exato do edital','1.4.4',[
'O edital delimita: arts. 1 a 4; 5 a 17; 18 e 19; 29 e 30; 37 a 41; 44 a 75. Organize a leitura por blocos: fundamentos e objetivos, direitos, organização federativa, município, Administração e Legislativo.',
'Fundamentos da República (art. 1) não são os objetivos fundamentais (art. 3), nem os princípios das relações internacionais (art. 4). Faça cartões separados. Direitos fundamentais incluem direitos individuais, sociais, nacionalidade e direitos políticos.',
'No Legislativo, diferencie competências do Congresso, Câmara e Senado e o papel do controle externo. Nos arts. 37 a 41, destaque ingresso, cargos, remuneração, acumulação e estabilidade. Leia exceções e requisitos junto com as regras.'
],'Dignidade da pessoa humana é fundamento; construir uma sociedade livre, justa e solidária é objetivo fundamental.','Decorar apenas o art. 37 deixa grande parte da faixa expressa do edital sem leitura.' , 'Quais artigos constitucionais do edital tratam especificamente do Município?','Arts. 29 e 30, além das outras faixas indicadas.',sources.cf),
L('l02','leg','Lei Orgânica e organização municipal','1.4.1; 1.4.3',[
'A Lei Orgânica organiza o Município dentro da Constituição. Estude autonomia municipal, competências, Câmara, prefeito e relações entre os Poderes. Interesse local e suplementação legislativa devem ser entendidos em conjunto com os arts. 29 e 30 da Constituição.',
'A Lei 7.671/1991 trata da organização administrativa do Executivo e recebeu alterações. Monte um quadro com órgão, natureza, atribuições e vinculação usando a redação apresentada na fonte oficial e conferindo os atos modificadores.',
'Não memorize organogramas de notícias antigas como se fossem a lei vigente. Ao estudar, anote o artigo e a versão consultada. Normas revogadas e textos riscados são úteis para perceber mudanças, mas não devem ser lidos como regra atual.'
],'Uma pergunta sobre competências da Câmara pede a Lei Orgânica; uma sobre atribuições de órgãos do Executivo pode exigir a lei de organização.','A data escrita no anexo pode divergir do cadastro legal: pesquise por número e ano, conferindo a norma correta.' , 'Qual norma é a base de organização política do Município?','A Lei Orgânica municipal.',sources.lom),
L('l03','leg','Estatuto dos servidores de Curitiba','1.4.2',[
'O Estatuto local é a Lei 1.656/1958, com alterações. Separe a leitura em ingresso e movimentação, direitos e vantagens, licenças, deveres, proibições e disciplina. Não substitua essa lei pela Lei Federal 8.112, que trata de outro regime.',
'Para cada instituto, responda: o que é, quem tem direito, quem decide, quais requisitos e qual prazo? Transforme respostas curtas em cartões. Prazos e condições devem vir do artigo vigente; não suponha que regras de outro município coincidam.',
'Faça uma segunda leitura só das exceções: termos como “salvo”, “vedado”, “poderá” e “deverá” costumam mudar a conclusão. Relacione o bloco disciplinar ao tópico de Conhecimentos Específicos para evitar estudar duas vezes sem integração.'
],'Tabela de estudo: licença → hipótese legal → requisito → autoridade → prazo → artigo. Preencha enquanto lê a fonte, não por memória de apostila antiga.','Nomeação, posse e exercício designam momentos distintos.' , 'Qual estatuto deve orientar o estudo municipal?','Lei Municipal 1.656/1958 e alterações.',sources.estatuto),
L('l04','leg','Improbidade administrativa atualizada','1.4.5',[
'A Lei 8.429/1992 foi significativamente alterada pela Lei 14.230/2021. Estude pela redação atualizada, identificando conduta dolosa, enquadramento legal e sanções. A mera voluntariedade não equivale automaticamente ao dolo exigido pela lei.',
'Os grandes grupos de atos envolvem enriquecimento ilícito, prejuízo ao erário e violação de princípios nas hipóteses legais. Para cada caso, relacione a conduta ao tipo e aos elementos exigidos; não basta invocar genericamente moralidade.',
'Compare responsabilidade disciplinar com improbidade: são regimes diferentes. Ao resolver questões antigas, verifique se a redação legal mudou; um gabarito correto em 2019 pode não servir para o regime atual.'
],'Receber vantagem indevida em razão do cargo exige examinar o tipo legal correspondente; atraso acidental não pode ser rotulado automaticamente como improbidade.','A redação antiga que admitia culpa em certos casos não deve ser transportada sem atualização.' , 'Qual elemento subjetivo a lei atual exige para os atos tipificados?','Dolo, nos termos da Lei de Improbidade.',sources.improbidade),
L('l05','leg','LAI e proteção de dados no poder público','1.4.6; 1.4.10',[
'A Lei de Acesso à Informação estabelece transparência como regra, com restrições previstas em lei. Transparência ativa é divulgação por iniciativa do órgão; passiva responde a pedidos. O requerente não precisa apresentar motivos para solicitar informação de interesse público.',
'Se a informação estiver disponível, o acesso deve ser imediato; quando isso não for possível, a LAI prevê prazo de até 20 dias, prorrogável por 10 mediante justificativa expressa. Revise também classificação e proteção de informações pessoais.',
'O edital cobra o Capítulo IV da LGPD, dedicado ao poder público. Tratamento deve atender finalidade pública e atribuições legais, com transparência sobre hipóteses e práticas. LAI e LGPD devem ser articuladas: nem toda informação pessoal é de divulgação irrestrita e nem todo dado público é sigiloso.'
],'Publicar a estrutura do órgão é transparência ativa. Responder a um pedido individual de informação é transparência passiva.','Consentimento não é a única base jurídica de tratamento de dados no setor público.' , 'Qual o prazo da LAI quando o acesso imediato não é possível?','Até 20 dias, prorrogáveis por mais 10 com justificativa expressa.',sources.lai),
L('l06','leg','Prioridade de atendimento e ECA','1.4.7–1.4.8',[
'A Lei 10.048 define pessoas com prioridade e recebeu alterações. Leia a lista atual na fonte, incluindo condições e regras específicas para doadores de sangue. Não presuma que todas as prioridades têm idêntico tratamento em toda legislação.',
'No ECA, criança é pessoa com menos de 12 anos; adolescente tem entre 12 e 18 anos, com hipóteses legais excepcionais de aplicação além dessa faixa. O edital indica disposições preliminares e direitos fundamentais.',
'Proteção integral e prioridade absoluta orientam o Estatuto. Estude vida e saúde, liberdade, respeito e dignidade, convivência familiar e comunitária, educação, cultura, esporte, lazer e profissionalização. Prioridade não elimina garantias e requisitos legais.'
],'Uma pessoa de 11 anos é criança; ao completar 12, enquadra-se como adolescente para a definição do ECA.','Não limite atendimento prioritário apenas a pessoas idosas e gestantes.' , 'Como o ECA define criança?','Pessoa até 12 anos de idade incompletos.',sources.eca),
L('l07','leg','LINDB: decisões e segurança jurídica','1.4.9 — arts. 20 a 30',[
'Os arts. 20 a 30 da LINDB orientam aplicação do direito público com atenção à realidade, consequências e segurança jurídica. Decisão baseada apenas em valores abstratos deve considerar consequências práticas.',
'A motivação deve demonstrar necessidade e adequação da medida e avaliar alternativas. Na invalidação de atos, contratos e processos, considere as consequências jurídicas e administrativas nos termos legais. A interpretação da gestão pública também observa obstáculos e dificuldades reais.',
'Não confunda atenção às consequências com autorização para descumprir a lei. Estude regime de transição, orientações gerais da época e responsabilidade pessoal por dolo ou erro grosseiro na forma do art. 28.'
],'Ao invalidar uma medida administrativa, a decisão precisa enfrentar seus efeitos e a forma de regularização quando cabível, em vez de apenas citar um princípio abstrato.','Consequencialismo jurídico não é “o fim justifica qualquer meio”.' , 'O que o art. 20 exige considerar ao decidir com base em valores abstratos?','As consequências práticas da decisão.',sources.lindb)
];
